// Accept only a positive integer ticket_id from the JSON body. Anything else -> 0 (matches no ticket).
const b = $input.first().json.body || {};
const raw = String(b.ticket_id ?? '');
const id = /^[0-9]{1,9}$/.test(raw) ? parseInt(raw, 10) : 0;
return [{ json: { ticketId: id } }];
